def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Restore the frame around the patterned area.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                if r < 2 or c < 2:
                    out[r][c] = 1
                elif r == 2 or c == 2:
                    out[r][c] = 4

    # Learn the repeating horizontal color cycle from intact adjacent cells.
    edge_counts = {}
    frequency = {}
    for r in range(3, h):
        for c in range(3, w):
            v = grid[r][c]
            if v:
                frequency[v] = frequency.get(v, 0) + 1
            if c + 1 < w and v and grid[r][c + 1]:
                nxt = grid[r][c + 1]
                edge_counts.setdefault(v, {})
                edge_counts[v][nxt] = edge_counts[v].get(nxt, 0) + 1

    successor = {
        v: max(edges, key=edges.get)
        for v, edges in edge_counts.items()
    }

    # Find the strongest cycle in the learned successor mapping.
    cycles = []
    for start in successor:
        path = []
        seen = {}
        v = start
        while v in successor and v not in seen:
            seen[v] = len(path)
            path.append(v)
            v = successor[v]
        if v in seen:
            cyc = path[seen[v]:]
            if cyc and cyc not in cycles:
                cycles.append(cyc)

    cycle = max(
        cycles,
        key=lambda cyc: (sum(frequency.get(v, 0) for v in cyc),
                         sum(edge_counts.get(v, {}).get(successor.get(v), 0)
                             for v in cyc)),
        default=[]
    )
    cycle_set = set(cycle)
    predecessor = {cycle[(i + 1) % len(cycle)]: cycle[i]
                   for i in range(len(cycle))} if cycle else {}

    # Fill patterned holes by continuing the cycle from the nearest known cell.
    for r in range(3, h):
        for c in range(3, w):
            if grid[r][c] != 0:
                continue
            anchors = []
            for x in range(3, w):
                if grid[r][x] in cycle_set:
                    anchors.append((abs(x - c), x, grid[r][x]))
            if not anchors:
                continue
            _, x, value = min(anchors)
            if x < c:
                for _ in range(c - x):
                    value = successor[value]
            else:
                for _ in range(x - c):
                    value = predecessor[value]
            out[r][c] = value

    return out
